--
-- Table structure for table `meter_records`
--

DROP TABLE IF EXISTS `meter_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `meter_records` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `room_id` bigint NOT NULL,
  `building_id` bigint DEFAULT NULL COMMENT '楼栋ID（冗余字段）',
  `month` date NOT NULL COMMENT '结算月份（每月1号）',
  `ac_meter_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '空调电表编号',
  `previous_reading` decimal(12,2) DEFAULT NULL COMMENT '上月普通电表读数',
  `current_reading` decimal(12,2) DEFAULT NULL COMMENT '本月普通电表读数',
  `total_degree` decimal(12,2) DEFAULT NULL COMMENT '普通用电量',
  `ac_previous_reading` decimal(12,2) DEFAULT NULL COMMENT '上月空调读数',
  `ac_current_reading` decimal(12,2) DEFAULT NULL COMMENT '本月空调读数',
  `ac_degree` decimal(12,2) DEFAULT NULL COMMENT '空调用电量',
  `electricity_price` decimal(10,4) DEFAULT NULL COMMENT '本月电价快照',
  `ac_unit_price` decimal(10,4) DEFAULT NULL COMMENT '空调平均单价',
  `total_fee` decimal(12,2) DEFAULT NULL COMMENT '普通电费',
  `ac_fee` decimal(12,2) DEFAULT NULL COMMENT '空调电费',
  `status` enum('normal','abnormal','manual') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '正常/异常/手工',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime DEFAULT (now()),
  `updated_at` datetime DEFAULT (now()),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_room_month` (`room_id`,`month`),
  KEY `idx_month` (`month`),
  KEY `idx_building_month` (`building_id`,`month`),
  CONSTRAINT `meter_records_ibfk_1` FOREIGN KEY (`room_id`) REFERENCES `rooms` (`id`),
  CONSTRAINT `meter_records_ibfk_2` FOREIGN KEY (`building_id`) REFERENCES `buildings` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=107 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='电表记录';
/*!40101 SET character_set_client = @saved_cs_client */;

