DROP TABLE IF EXISTS `monthly_settlements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `monthly_settlements` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `month` date NOT NULL COMMENT '结算月份',
  `employee_id` bigint NOT NULL,
  `room_id` bigint NOT NULL,
  `rent_should` decimal(10,2) DEFAULT NULL COMMENT '应住房租',
  `rent_actual` decimal(10,2) DEFAULT NULL COMMENT '实扣房租',
  `stay_days` int DEFAULT NULL COMMENT '实际入住天数',
  `electricity_fee` decimal(10,2) DEFAULT NULL COMMENT '个人普通电费',
  `ac_electricity_fee` decimal(10,2) DEFAULT NULL COMMENT '个人空调电费',
  `water_fee` decimal(10,2) DEFAULT NULL COMMENT '个人水费',
  `deduction_minus` decimal(10,2) DEFAULT NULL COMMENT '补扣-',
  `deduction_plus` decimal(10,2) DEFAULT NULL COMMENT '补扣+',
  `total_amount` decimal(10,2) DEFAULT NULL COMMENT '最终扣款',
  `status` enum('draft','generated','locked') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '草稿/已生成/已锁定',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime DEFAULT (now()),
  `updated_at` datetime DEFAULT (now()),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_month_employee` (`month`,`employee_id`),
  KEY `employee_id` (`employee_id`),
  KEY `room_id` (`room_id`),
  KEY `idx_status` (`status`),
  KEY `idx_month` (`month`),
  CONSTRAINT `monthly_settlements_ibfk_1` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`),
  CONSTRAINT `monthly_settlements_ibfk_2` FOREIGN KEY (`room_id`) REFERENCES `rooms` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='月度结算';
