--
-- Table structure for table `room_main_meter_records`
--

DROP TABLE IF EXISTS `room_main_meter_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `room_main_meter_records` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `building_id` bigint NOT NULL,
  `room_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '房号（如201、202）',
  `month` date NOT NULL COMMENT '结算月份（每月1号）',
  `meter_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '总电表编号',
  `previous_reading` decimal(12,2) DEFAULT NULL COMMENT '上月读数',
  `current_reading` decimal(12,2) DEFAULT NULL COMMENT '本月读数',
  `total_degree` decimal(12,2) DEFAULT NULL COMMENT '用电量',
  `electricity_price` decimal(10,4) DEFAULT NULL COMMENT '电价',
  `total_fee` decimal(12,2) DEFAULT NULL COMMENT '电费',
  `common_degree` decimal(12,2) DEFAULT NULL COMMENT '公共用电量（总表-空调表）',
  `common_fee` decimal(12,2) DEFAULT NULL COMMENT '公共电费（总表电费-空调电费）',
  `status` enum('pending','recorded','calculated') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '待录入/已录入/已计算',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime DEFAULT (now()),
  `updated_at` datetime DEFAULT (now()),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_building_room_month` (`building_id`,`room_no`,`month`),
  KEY `idx_main_meter_building_room` (`building_id`,`room_no`),
  KEY `idx_main_meter_month` (`month`),
  CONSTRAINT `room_main_meter_records_ibfk_1` FOREIGN KEY (`building_id`) REFERENCES `buildings` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='房号总电表记录';
/*!40101 SET character_set_client = @saved_cs_client */;

