--
-- Table structure for table `rooms`
--

DROP TABLE IF EXISTS `rooms`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rooms` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `building_id` bigint NOT NULL,
  `room_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '房号',
  `room_unit` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '室号',
  `room_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '房间名称',
  `meter_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电表编号',
  `ac_meter_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '空调电表编号',
  `water_meter_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '水表编号',
  `electricity_price` decimal(10,4) DEFAULT NULL COMMENT '默认电价',
  `water_unit_price` decimal(10,4) DEFAULT '3.5000' COMMENT '默认水价',
  `rent_standard` decimal(10,2) DEFAULT NULL COMMENT '房租标准',
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime DEFAULT (now()),
  `updated_at` datetime DEFAULT (now()),
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_building_room_name` (`building_id`,`room_no`,`room_name`),
  KEY `idx_building_room` (`building_id`,`room_no`),
  KEY `idx_room_name` (`room_name`),
  CONSTRAINT `rooms_ibfk_1` FOREIGN KEY (`building_id`) REFERENCES `buildings` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=99 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='房间(宿舍)';
/*!40101 SET character_set_client = @saved_cs_client */;

